import{_ as e,o as t,c as r,a0 as d}from"./chunks/framework.C4u0TEY0.js";const u=JSON.parse('{"title":"架构","description":"","frontmatter":{},"headers":[],"relativePath":"zh/internals/architecture.md","filePath":"zh/internals/architecture.md"}'),o={name:"zh/internals/architecture.md"};function n(c,a,s,i,p,l){return t(),r("div",null,[...a[0]||(a[0]=[d(`<h1 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to &quot;架构&quot;">​</a></h1><p>apk.js 分层组织，每一层把更窄的数据交给下一层。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>APK zip</span></span>
<span class="line"><span>  └── 解析层        dex/、res/     字节 → 类、资源、布局</span></span>
<span class="line"><span>        └── 运行时  runtime/       DEX → JavaVM、对象、解释器</span></span>
<span class="line"><span>              └── Framework        Java API 调用 → 视图树和像素</span></span>
<span class="line"><span>                    └── 引擎       生命周期、屏幕、输入</span></span></code></pre></div><h2 id="分层" tabindex="-1">分层 <a class="header-anchor" href="#分层" aria-label="Permalink to &quot;分层&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>目录</th><th>职责</th></tr></thead><tbody><tr><td>解析层</td><td><code>src/dex</code>、<code>src/res</code></td><td>读取二进制格式：DEX、AXML、ARSC</td></tr><tr><td>运行时</td><td><code>src/runtime</code></td><td>类注册表、值模型、字节码解释器</td></tr><tr><td>Framework</td><td><code>src/framework</code></td><td>用 Canvas 和 JavaScript 实现的 Android API</td></tr><tr><td>入口</td><td><code>apk.js</code></td><td>公开 API、设备设置、文件加载</td></tr></tbody></table><h2 id="运行时" tabindex="-1">运行时 <a class="header-anchor" href="#运行时" aria-label="Permalink to &quot;运行时&quot;">​</a></h2><p><code>JavaVM</code> 持有类注册表、解释器、堆和方法栈。值都是带描述符的 JavaScript 对象：实例用 <code>JavaObject</code>，数组用 <code>JavaArray</code>，基本类型直接用数字或字符串。</p><p><code>DexInterpreter</code> 遍历字节码，每帧维护一个寄存器文件。方法调用会转回 VM，VM 先查 native 定义，再查 DEX 类。</p><h2 id="framework" tabindex="-1">Framework <a class="header-anchor" href="#framework" aria-label="Permalink to &quot;Framework&quot;">​</a></h2><p>Framework 是一组 native 类定义。每个定义用 JavaScript 和 Canvas 2D API 实现 Android 类的一部分。<code>View</code> 保存几何、布局参数和绘制方法；<code>ViewGroup</code> 额外负责测量和排布子视图。</p><p>引擎把 Framework 接到 canvas 上：创建初始 Activity、驱动 <code>onCreate</code>、推进 choreographer 循环，并把指针事件分派到视图树。</p><h2 id="引擎" tabindex="-1">引擎 <a class="header-anchor" href="#引擎" aria-label="Permalink to &quot;引擎&quot;">​</a></h2><p><code>EmulatorEngine.start(apk)</code> 会准备好 VM、注册 native 类、填充虚拟文件系统、安装传感器源，然后启动 launcher Activity。<code>attachCanvas</code> 绑定用于渲染和输入的 canvas。</p><p>屏幕记录脏状态。视图调用 <code>invalidate</code> 时，引擎把屏幕标记为脏，在下一帧重绘。</p>`,14)])])}const m=e(o,[["render",n]]);export{u as __pageData,m as default};
